-- startsWithCaseInsensitiveUTF8 and endsWithCaseInsensitiveUTF8 must match code points like positionCaseInsensitiveUTF8,
-- also when the match and the needle differ in byte length. Each function prints const/const, column/const, column/column, const/column.

SELECT 'startsWith';
WITH 'ß' AS h, 'ẞ' AS n SELECT 'sharp s to capital', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'ẞ' AS h, 'ß' AS n SELECT 'capital to sharp s', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'xß' AS h, 'ẞ' AS n SELECT 'capital at end', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'ßx' AS h, 'ẞ' AS n SELECT 'capital at start', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'ⱥ' AS h, 'Ⱥ' AS n SELECT 'A-bar to a-bar', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'Ⱥ' AS h, 'ⱥ' AS n SELECT 'a-bar to A-bar', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'xxⱥ' AS h, 'Ⱥ' AS n SELECT 'a-bar at end', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'Ⱥxx' AS h, 'ⱥ' AS n SELECT 'a-bar at start', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'STRAẞE' AS h, 'straße' AS n SELECT 'STRASSE', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'ß' AS h, 'ss' AS n SELECT 'sharp s vs ss', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH concat(char(0xE2, 0x84, 0xAA), 'x', char(0xE2, 0x84, 0xAA)) AS h, 'k' AS n SELECT 'kelvin vs k', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'kxk' AS h, char(0xE2, 0x84, 0xAA) AS n SELECT 'k vs kelvin', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH concat(char(0xE2, 0x84, 0xAA), 'x', char(0xE2, 0x84, 0xAA)) AS h, char(0xE2, 0x84, 0xAA) AS n SELECT 'kelvin to kelvin', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'Hello World' AS h, 'hELLO' AS n SELECT 'ascii prefix', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'Hello World' AS h, 'wORLD' AS n SELECT 'ascii suffix', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'abc' AS h, '' AS n SELECT 'empty needle', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH '' AS h, '' AS n SELECT 'both empty', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH '' AS h, 'a' AS n SELECT 'empty haystack', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;
WITH 'ab' AS h, 'abc' AS n SELECT 'needle longer', startsWithCaseInsensitiveUTF8(h, n), startsWithCaseInsensitiveUTF8(materialize(h), n), startsWithCaseInsensitiveUTF8(materialize(h), materialize(n)), startsWithCaseInsensitiveUTF8(h, materialize(n)), positionCaseInsensitiveUTF8(h, n) = 1;

