SELECT 'rows of different lengths';
SELECT h, n, startsWithCaseInsensitiveUTF8(h, n), endsWithCaseInsensitiveUTF8(h, n) FROM values('h String, n String', ('ß', 'ẞ'), ('xß', 'ẞ'), ('ẞx', 'ß'), ('Ⱥ', 'ⱥ'), ('xⱥ', 'Ⱥ'), ('abc', ''), ('', 'a'), ('AbC', 'abc'));
SELECT h, startsWithCaseInsensitiveUTF8(h, 'ẞ'), endsWithCaseInsensitiveUTF8(h, 'ẞ') FROM values('h String', ('ß'), ('xß'), ('ßx'), (''), ('ẞ'));
